<?php require_once __DIR__.'/config.php';$id=(int)($_GET['id']??0);$thread=null;foreach(data_load('threads.json') as $t)if((int)$t['id']===$id)$thread=$t;if(!$thread){http_response_code(404);exit('Тема не найдена');}$replies=data_load('replies_'.$id.'.json');?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($thread['title'])?> — GREFFRLEND</title><link rel="stylesheet" href="style.css"></head><body><header class="top"><div class="wrap nav"><a class="logo" href="index.php">GREFFRLEND</a><nav><a href="index.php">Главная</a><a href="rules.php">Правила</a></nav></div></header><main class="wrap"><article class="card"><div class="category">ТЕМА</div><h1><?=e($thread['title'])?></h1><p class="muted"><?=e($thread['author'])?> · <?=e($thread['created_at'])?></p><p><?=nl2br(e($thread['content']))?></p></article><?php foreach($replies as $r):?><div class="card"><b><?=e($r['author'])?></b><div class="muted"><?=e($r['created_at'])?></div><p><?=nl2br(e($r['message']))?></p></div><?php endforeach;?><?php if(user()):?><div class="card form"><h2>Ответить</h2><form method="post" action="reply.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="thread_id" value="<?=$id?>"><textarea name="message" required></textarea><button class="btn">Отправить</button></form></div><?php else:?><div class="card">Чтобы отвечать, <a href="login.php">войдите</a> или <a href="register.php">зарегистрируйтесь</a>.</div><?php endif;?></main></body></html>